"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["26983"],{63999(e){e.exports=JSON.parse('{"id":"FIN-721","slug":"loss-aversion","term":"Loss Aversion","also_known_as":[],"difficulty":"Intermediate","definition":"Loss aversion is the tendency for people to feel the pain of losses more strongly than the pleasure of equivalent gains.","explanation":["Research by psychologists Daniel Kahneman and Amos Tversky suggested that, for many people, losing a sum of money feels roughly twice as bad as gaining the same amount feels good. This imbalance affects many financial decisions.","For example, many people will turn down a coin toss that offers a 50% chance of winning 110 and a 50% chance of losing 100, even though the bet has a positive expected value. The potential loss looms larger than the slightly bigger potential gain.","In investing, loss aversion can lead to several costly behaviours. Investors may hold on to losing investments too long, hoping to avoid realizing a loss, while selling winning investments too early. They may avoid investing in shares altogether because of fear of short-term losses, even when they have a long time horizon. They may panic and sell during market falls.","Loss aversion is a central idea in behavioural finance and prospect theory. Being aware of it can help investors make more balanced decisions, for example by focusing on long-term goals, diversifying, and following a plan rather than reacting emotionally to short-term changes in value."],"note":"","total":1725,"prev":{"slug":"look-ahead-bias","term":"Look-Ahead Bias"},"next":{"slug":"loss-carryforward","term":"Loss Carryforward"}}')}}]);